export function getAllTracks(): TrackItem[] {
  return TRACKS;
}

export function getTrackById(id: string): TrackItem | undefined {
  return TRACKS.find((t) => t.id === id);
}

export function getTrackBySlug(category: string, slug: string): TrackItem | undefined {
  return TRACKS.find((t) => t.category === category && t.slug === slug);
}

export function getTracksByCategory(category: string): TrackItem[] {
  if (category === "all") return TRACKS;
  return TRACKS.filter((t) => t.category === category);
}

export function getCategoryInfo(category: string): CategoryInfo | undefined {
  return CATEGORIES.find((c) => c.id === category);
}

